WITH remaining_keys AS (SELECT id, customer_id FROM orders INTERSECT ALL SELECT id, customer_id FROM orders WHERE customer_id = 28), verified AS (SELECT s.* FROM orders s INNER JOIN remaining_keys k ON s.id = k.id AND s.customer_id = k.customer_id) SELECT DATE_TRUNC('WEEK', order_date) AS week_start, STDDEV_SAMP(discount) AS discount_stddev, APPROX_PERCENTILE(amount, 0.5) AS amount_p50, COUNT_IF(channel = 'partner') AS partner_events, COUNT(*) FILTER (WHERE status = 'RETURNED') AS returned_rows, APPROX_PERCENTILE(shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS shipping_fee_quartiles, COUNT(*) FILTER (WHERE status = 'PENDING') AS pending_rows FROM verified GROUP BY CUBE (DATE_TRUNC('WEEK', order_date)) HAVING pending_rows >= 1 ORDER BY returned_rows ASC NULLS LAST;
